def solve(grid):
    # Find the position of the unique cell with value 8
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])
    eight_pos = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 8:
                eight_pos = (i, j)
                break
        if eight_pos is not None:
            break
    if eight_pos is None:
        # No 8 present – return a 3×3 zero grid (should not happen)
        return [[0,0,0],[0,0,0],[0,0,0]]
    r, c = eight_pos

    # Gather colors of the eight neighbours (excluding 0 and 8)
    from collections import Counter
    neighbour_counts = Counter()
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                v = grid[nr][nc]
                if v != 0 and v != 8:
                    neighbour_counts[v] += 1

    # Determine the arm colour (most common neighbour colour)
    arm_color = neighbour_counts.most_common(1)[0][0] if neighbour_counts else 0

    # Build the 3×3 output grid
    out = [[0]*3 for _ in range(3)]
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            nr, nc = r + dr, c + dc
            out_r, out_c = dr + 1, dc + 1
            if 0 <= nr < rows and 0 <= nc < cols:
