                if v != 0 and v != 8:
                    out[out_r][out_c] = v
                else:
                    out[out_r][out_c] = 0
            else:
                out[out_r][out_c] = 0

    # Fill the centre cell with the arm colour
    out[1][1] = arm_color
    return out

